import { task, types } from "hardhat/config";
import { deployOrLoadAndVerify } from "./utils";

task("deploy-multisig", "Deploy multisig")
  .addParam("owners", "comma seperated 0x addresses of the safe owners")
  .addOptionalParam(
    "requirement",
    "how much confirmations needed to make a tx",
    1,
    types.int
  )
  .setAction(async ({ owners, requirement }, hre) => {
    const _owners = owners.split(",");
    const _requirement = requirement || _owners.length;

    await deployOrLoadAndVerify(hre, "MultiSigWallet", "MultiSigWallet", [
      _owners, // address[] memory _owners,
      _requirement, // uint256 _required
    ]);
  });

import { task } from "hardhat/config";
import { deployOrLoadAndVerify, getOutputAddress } from "./utils";

task("deploy-stablecoin", "Deploys the stablecoin")
  .addParam("symbol", "symbol of the token (eg: USD-A)")
  .addParam("name", "name of the token (eg: USD-A Coin)")
  .addOptionalParam("multisig", "address of the multisig owner")
  .setAction(async ({ name, symbol, multisig }, hre) => {
    const _wallet = multisig || (await getOutputAddress(hre, "MultiSigWallet"));

    await deployOrLoadAndVerify(hre, symbol, "StablecoinImpl", [
      name, // string memory _name,
      symbol, // string memory _symbol,
      _wallet, // address _wallet
    ]);
  });

import { time, loadFixture } from "@nomicfoundation/hardhat-network-helpers";
import { anyValue } from "@nomicfoundation/hardhat-chai-matchers/withArgs";
import { expect } from "chai";
import { ethers } from "hardhat";

describe("Lock", function () {
  // We define a fixture to reuse the same setup in every test.
  // We use loadFixture to run this setup once, snapshot that state,
  // and reset Hardhat Network to that snapshot in every test.
  async function fixture() {
    const [owner, otherAccount] = await ethers.getSigners();

    const MultiSigWallet = await ethers.getContractFactory("MultiSigWallet");
    const multiSigWallet = await MultiSigWallet.deploy(
      [owner.address, otherAccount.address],
      2
    );

    const StablecoinImpl = await ethers.getContractFactory("StablecoinImpl");
    const usda = await StablecoinImpl.deploy(
      "USDA Coin",
      "USDA",
      multiSigWallet.address
    );

    return { multiSigWallet, usda, owner, otherAccount };
  }

  describe("Deployment", function () {
    it("Should set the right unlockTime", async function () {
      const { multiSigWallet, usda, owner, otherAccount } = await loadFixture(
        fixture
      );

      await multiSigWallet
        .connect(owner)
        .submitTransaction(
          usda.address,
          0,
          usda.interface.encodeFunctionData("mint", [owner.address, "1000"])
        );

      await multiSigWallet.connect(otherAccount).confirmTransaction("0");
      // await multiSigWallet.connect(owner).confirmTransaction("0");
    });

    // it("Should set the right owner", async function () {
